  ('ada31a80-e0c7-5a58-8078-dd9e612eb330', null, (select id from public.skills where slug = 'read-g12-theme-summary'), null, 'easy',
   $q$Which statement best expresses a central theme of the passage?$q$, $q$[{"text":"The names people give a place hold their history, and preserving them gives ordinary people a voice in the record.","is_correct":true},{"text":"Young workers should always follow their employers' instructions without question.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"Official surveyors in the 1800s usually named places after themselves.","is_correct":false,"misconception_token":"overgeneralizes"},{"text":"Maps are more accurate when surveyors measure carefully in steps and angles.","is_correct":false,"misconception_token":"topic-not-theme"}]$q$::jsonb, $q$The names people give a place hold their history, and preserving them gives ordinary people a voice in the record.$q$, $q$Wendell's notebook records names tied to family and farming history, and the appendix credits the residents. The passage does not claim all surveyors named places after themselves.$q$, 'draft', '640cdf0e-ec79-5269-8460-e6e48ea6f1a2')
