values
  ('641f584f-329f-507e-ae77-f30ca1d1e2ab', null, (select id from public.skills where slug = 'read-g12-theme-summary'), null, 'medium',
   $q$What does the coach's response at the edge of the strip contribute to the passage?$q$, $q$[{"text":"It shows that the coach did not notice what had happened during the bout.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"It shows that the coach is angry about the call but hides it to avoid a scene.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"It suggests that Marisol will quit fencing because of the disappointing loss.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"By praising her footwork, he values how she competed over the result, quietly supporting the theme.","is_correct":true}]$q$::jsonb, $q$By praising her footwork, he values how she competed over the result, quietly supporting the theme.$q$, $q$The coach says nothing about the call and praises her performance, emphasizing conduct and growth rather than the score. No anger is described, and the gym's silence shows everyone noticed.$q$, 'draft', '66abf76b-c2d5-521f-bd75-08325eac49d5')
