  ('316bf6e2-7a85-534f-a572-3616d49d5d52', null, (select id from public.skills where slug = 'read-g12-word-parts'), null, 'medium',
   $q$The root err means "to wander" or "to make a mistake," and the suffix -ous means "full of" or "having." What is an "erroneous" bit?$q$, $q$[{"text":"A bit that holds the wrong value","is_correct":true},{"text":"A bit that is missing from the message","is_correct":false,"misconception_token":"too-narrow"},{"text":"A bit that adds extra checking information","is_correct":false,"misconception_token":"confuses-related-idea"},{"text":"A bit that travels an unusually long route","is_correct":false,"misconception_token":"too-literal"}]$q$::jsonb, $q$A bit that holds the wrong value$q$, $q$Erroneous means containing a mistake, and the computers "flip it back," which only makes sense for a bit with the wrong value. The extra checking bits are added on purpose and are not the mistaken ones.$q$, 'draft', '522d847e-ee97-58b3-95a7-1ab8533b8011')
